pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address _recipient) public {
        vm.assume(_recipient != address(this));
        vm.deal(address(c), 1 ether);

        uint256 recipientBalanceBefore = _recipient.balance;

        vm.prank(address(this));
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", _recipient));

        if (success) {
            assertTrue(_recipient.balance == recipientBalanceBefore + address(c).balance);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address _recipient) public {
        vm.assume(_recipient != address(0));
        vm.assume(_recipient != address(c));

        // Fund the contract with some ether
        uint256 amount = 1 ether;
        vm.deal(address(c), amount);

        // Record balances before
        uint256 recipientBalanceBefore = _recipient.balance;

        // Owner calls withdrawAll
        vm.prank(address(this));
        c.withdrawAll(_recipient);

        // Check that the recipient's balance increased by exactly amount
        assertTrue(_recipient.balance == recipientBalanceBefore + amount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.deal(sender, amount);
        vm.prank(sender);
        payable(address(c)).transfer(amount);
        vm.prank(sender);
        c.withdrawAll(sender);
        assertTrue(sender.balance >= amount);
    }
}
